import { StudioProApi } from "@mendix/extensions-api";
import { DefaultTheme } from "styled-components";
import { RUNTIME_NOT_CONNECTED_ERROR_MESSAGE } from "../constants/studioPro";
import { DARK_VARIABLE_COLORS, LIGHT_VARIABLE_COLORS } from "../constants/styles";
import { agentDocumentTypeId } from "../main";
import { Agent, AgentDocument, TestVariable, Variable } from "../types/agent";
import { Response } from "../types/playground";
import { HighlightRule } from "../ui/components/TextAreaLabeled";
import { getEntity, getEntityAttributeNames } from "./domainModelUtils";
import { isDarkTheme } from "./userPreferences";

export function createNewAgent(): Agent {
    return {
        description: "",
        systemPrompt: "",
        userPrompt: "",
        usageType: "Task",
        variables: [],
        tools: [],
    };
}

export function createNewAgentDocument(): AgentDocument {
    return {
        $ID: "",
        name: "",
        excluded: false,
        documentType: agentDocumentTypeId,
        contents: createNewAgent(),
    };
}

export const updateAgentDocument = (studioPro: StudioProApi, documentId: string) => async (agent: Agent) => {
    try {
        await studioPro.app.model.customBlobDocuments.updateDocumentContent(documentId, agent);
    } catch (error) {
        await studioPro.ui.notifications.show({
            title: "Failed to save document",
            message: (error as Error).message,
        });
    }
};

export async function calculateVariables(studioPro: StudioProApi, agent: Agent): Promise<Variable[]> {
    const systemPromptPlaceholders = agent.systemPrompt.match(/\{\{([^}\s{]+)\}\}/g) || [];
    const userPromptPlaceholders = agent.userPrompt ? agent.userPrompt.match(/\{\{([^}\s{]+)\}\}/g) || [] : [];
    const placeholders: string[] = [...systemPromptPlaceholders, ...userPromptPlaceholders];

    if (placeholders.length === 0) {
        return Promise.resolve([]);
    }

    // The keys are only the part between {{}}
    const variableKeys: string[] = placeholders.map((match) => match.replace(/\{\{|\}\}/g, ""));

    // Remove duplicates
    const uniqueVariableKeys: string[] = [...new Set(variableKeys)];

    // Get or create Variable objects (keep the ones that already exist on the current agent)
    const currentVariables: Variable[] = agent.variables;
    const newVariables: Variable[] = uniqueVariableKeys.map((name) => {
        const existingVariable = currentVariables.find((v) => v.key === name);
        return (
            existingVariable || {
                key: name,
                isAttributeInEntity: false,
            }
        );
    });

    return checkAttributes(studioPro, newVariables, agent);
}

export const createHighlightRules = (variables: Variable[], theme: DefaultTheme): HighlightRule[] => {
    return variables.map((v, index) => ({
        pattern: new RegExp("\\{\\{" + v.key + "\\}\\}", "g"),
        style: {
            ...getVariableColors(index, isDarkTheme(theme)),
            borderRadius: "2px",
            borderWidth: "1px",
            borderStyle: "solid",
            margin: "0 -1px",
        },
    }));
};

function getVariableColors(index: number, isDarkTheme: boolean) {
    const colorPalette = isDarkTheme ? DARK_VARIABLE_COLORS : LIGHT_VARIABLE_COLORS;

    return {
        color: colorPalette[index % colorPalette.length][1],
        backgroundColor: colorPalette[index % colorPalette.length][0],
        borderColor: colorPalette[index % colorPalette.length][1],
    };
}

export async function checkAttributes(
    studioPro: StudioProApi,
    variables: Variable[],
    agent: Agent
): Promise<Variable[]> {
    const isEntityFound = await isAgentEntityFound(studioPro, agent);
    const attributeNames: string[] = await getAttributeNames(agent, studioPro);
    return variables.map((variable) => {
        const isAttributeInEntity = attributeNames.includes(variable.key);
        return {
            ...variable,
            isAttributeInEntity: isEntityFound === false || isAttributeInEntity,
        };
    });
}

export const isAgentEntityFound = async (studioPro: StudioProApi, agent: Agent): Promise<boolean> => {
    if (!agent.entity) {
        return true;
    }
    return (await getEntity(studioPro, agent.entity.qualifiedName)) !== undefined;
};

export const getMissingAttributes = async (studioPro: StudioProApi, agent: Agent): Promise<string[]> => {
    if (agent.variables.length === 0) {
        return [];
    }
    if (!agent.entity || !(await getEntity(studioPro, agent.entity.qualifiedName))) {
        return [];
    }
    return agent.variables.filter((v) => !v.isAttributeInEntity).map((v) => v.key);
};

const getAttributeNames = async (agent: Agent, studioPro: StudioProApi): Promise<string[]> => {
    if (!agent.entity) {
        return [];
    }
    const entity = await getEntity(studioPro, agent.entity.qualifiedName);
    if (!entity) {
        return [];
    }
    return (await getEntityAttributeNames(studioPro, entity)).sort();
};

export const getUnusedAttributes = async (studioPro: StudioProApi, agent: Agent): Promise<string[]> => {
    const attributeNames: string[] = await getAttributeNames(agent, studioPro);
    return attributeNames.filter((a) => !agent.variables.find((v) => v.key === a));
};

/**
 * Executes the agent test action with the given parameters.
 * @param studioPro - The StudioPro API instance.
 * @param parameters - The parameters to pass to the test request.
 * @returns A promise that resolves to the response of the action execution.
 */
export const executeTestAction = async (
    studioPro: StudioProApi,
    documentId: string,
    testVariables: TestVariable[]
): Promise<Response> => {
    // Transform variables to a key-value pair object
    const variables = testVariables.reduce<Record<string, string>>((acc, variable) => {
        acc[variable.key] = variable.value;
        return acc;
    }, {});

    const parameters = {
        documentId,
        variables: JSON.stringify(variables),
    };

    const response = (await studioPro.runtime.controller.executePreviewAction(
        "preview_agent_test",
        parameters
    )) as Response;
    return response;
};

/**
 * Tests the runtime connection by executing a non existing action.
 * @param studioPro - The StudioPro API instance.
 * @returns A promise that resolves to true if the connection is successful, otherwise false.
 */
export const testRuntimeConnection = async (studioPro: StudioProApi): Promise<boolean> => {
    try {
        const response = await studioPro.runtime.controller.executePreviewAction("preview_runtime_test", {});

        if (
            typeof response === "object" &&
            response !== null &&
            "error" in response &&
            response.error === RUNTIME_NOT_CONNECTED_ERROR_MESSAGE
        ) {
            return false;
        }

        return true;
    } catch {
        // If an error is thrown, it means the runtime is connected but the action doesn't exist
        return true;
    }
};
