import { CustomBlobDocument, StudioProApi } from "@mendix/extensions-api";
import { ModelDocument } from "../types/modelDocument";

export const getCustomBlobDocumentById = async (
    studioPro: StudioProApi,
    documentId: string
): Promise<CustomBlobDocument | undefined> => {
    const result = await studioPro.app.model.customBlobDocuments.getDocumentById(documentId);

    if (result !== undefined && "document" in result) {
        return result.document;
    }

    return undefined;
};

export const handleShowCustomBlobDocument = async (
    studioPro: StudioProApi,
    modelDocument: ModelDocument
): Promise<void> => {
    const document = await getCustomBlobDocumentById(studioPro, modelDocument.documentId);

    if (!document) {
        const errorMessage = "Could not find document.";
        const errorDetails = "This document might have been deleted or renamed. Please update the selection.";
        return await studioPro.ui.messageBoxes.show("error", errorMessage, errorDetails);
    }
    await studioPro.ui.editors.editDocument(modelDocument.documentId);
};
